def find_color_regions(grid, target_color):
    """Find connected component of target_color cells"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = []

    # Find starting points
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color and (r, c) not in visited:
                visited.add((r, c))
                queue.append((r, c))

    # Flood fill
    while queue:
        r, c = queue.pop(0)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
